#include <bits/stdc++.h>
using namespace std;

int main() {
    vector<int> inputs(2);
    for (int i = 0; i < 2; ++i) {
        cin >> inputs[i];
    }
    sort(inputs.begin(), inputs.end());
    int a = inputs[0], b = inputs[1];
    int prod = a * b;
    int conditions_map_value;
    if (a == 1) {
        conditions_map_value = 2 * ((b % 6 > 1) && (b % 6 < 5));
    } else if (a == 2) {
        if (b == 2) {
            conditions_map_value = 4;
        } else if (b == 3) {
            conditions_map_value = 2;
        } else if (b == 7) {
            conditions_map_value = 2;
        } else {
            conditions_map_value = 0;
        }
    } else {
        conditions_map_value = 0;
    }
    cout << (~1 & (prod - conditions_map_value)) << "\n";
    return 0;
}
